package sharks.lc8.models;

import com.fasterxml.jackson.annotation.JsonProperty;
import lombok.Builder;
import lombok.Getter;

/*
 The "device" block the server wants inside register and login requests.
 All values are fixed, our tests always pretend to be the same browser, so DeviceDto.builder().build() is enough everywhere.
 */
@Getter
// Builder generated by Lombok - compare with UserDto, where it is written by hand
@Builder
public class DeviceDto {

    // Java fields stay camelCase, @JsonProperty sends them as snake_case (device_id, user_agent).
    // @Builder.Default is required: without it Lombok ignores the value and the field becomes null.
    @JsonProperty("platform")
    @Builder.Default
    private final String platform = "WEB";

    @JsonProperty("device_id")
    @Builder.Default
    private final String deviceId = "9b07a82a58d36c9435a40704a8381570";

    @JsonProperty("device_model")
    @Builder.Default
    private final String deviceModel = "Web Windows Chrome 151";

    @JsonProperty("browser_name")
    @Builder.Default
    private final String browserName = "Chrome";

    @JsonProperty("browser_version")
    @Builder.Default
    private final String browserVersion = "151.0.0.0";

    @JsonProperty("os_version")
    @Builder.Default
    private final String osVersion = "10";

    @JsonProperty("user_agent")
    @Builder.Default
    private final String userAgent =
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36";

    @JsonProperty("language")
    @Builder.Default
    private final String language = "uk";
}